const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Call `operation` until it resolves.
 *
 * Retries with exponential backoff: the delay after a failed attempt starts
 * at `baseDelayMs` and doubles on each subsequent failure, capped at
 * `maxDelayMs`.
 */
export async function retry(operation, options = {}) {
  const maxAttempts = options.maxAttempts ?? 3;
  const baseDelayMs = options.baseDelayMs ?? 10;
  const maxDelayMs = options.maxDelayMs ?? 1000;
  let last;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await operation(attempt);
    } catch (error) {
      last = error;
      if (attempt < maxAttempts) {
        const delay = Math.min(baseDelayMs * 2 ** (attempt - 1), maxDelayMs);
        await sleep(delay);
      }
    }
  }
  throw new RetriesExhausted(maxAttempts, last);
}

