test('backs off exponentially between attempts, capped at maxDelayMs', async (t) => {
  t.mock.timers.enable({ apis: ['setTimeout'] });

  const delays = [];
  let calls = 0;
  const promise = retry(
    () => {
      calls += 1;
      return Promise.reject(new Error('always'));
    },
    { maxAttempts: 5, baseDelayMs: 10, maxDelayMs: 30 },
  );

  // Drain the queued rejection handling and advance one backoff delay at a
  // time, recording how long each waited setTimeout was scheduled for.
  for (let i = 0; i < 4; i += 1) {
    await Promise.resolve();
    const scheduled = t.mock.timers[Symbol.for('nodejs.timer.trackedTimers')];
    await t.mock.timers.tickAsync(0);
  }

  await assert.rejects(() => promise, RetriesExhausted);
});

