test('backs off exponentially between attempts, capped at maxDelayMs', async (t) => {
  t.mock.timers.enable({ apis: ['setTimeout'] });

  const delays = [];
  const originalSetTimeout = globalThis.setTimeout;
  t.mock.method(globalThis, 'setTimeout', (fn, ms, ...args) => {
    delays.push(ms);
    return originalSetTimeout(fn, 0, ...args);
  });

  await assert.rejects(
    () =>
      retry(() => Promise.reject(new Error('always')), {
        maxAttempts: 5,
        baseDelayMs: 10,
        maxDelayMs: 30,
      }),
    RetriesExhausted,
  );

  // 4 delays between 5 attempts: 10, 20, capped at 30, capped at 30.
  assert.deepEqual(delays, [10, 20, 30, 30]);
});

